-- Generated by pwc2dbt from PowerCenter mapping m_FL_JS_MARTS_ENRICHED, target ORDER_ITEM_ENRICHED.

with

sq_stg_order_items as (
    -- Source Qualifier SQ_STG_ORDER_ITEMS
    select
        stg_order_items.order_item_id,
        stg_order_items.order_id,
        stg_order_items.product_id
    from {{ ref('stg_order_items') }} as stg_order_items
),

sq_stg_orders as (
    -- Source Qualifier SQ_STG_ORDERS
    select
        stg_orders.order_id,
        stg_orders.customer_id,
        stg_orders.location_id,
        stg_orders.ordered_at_day,
        stg_orders.subtotal_cents,
        stg_orders.tax_paid_cents,
        stg_orders.order_total_cents,
        stg_orders.subtotal,
        stg_orders.tax_paid,
        stg_orders.order_total
    from {{ ref('stg_orders') }} as stg_orders
),

jnr_items_orders as (
    -- Joiner JNR_ITEMS_ORDERS
    -- Normal Join (master sq_stg_order_items, detail sq_stg_orders)
    select
        sq_stg_order_items.order_item_id,
        sq_stg_order_items.order_id,
        sq_stg_order_items.product_id,
        sq_stg_orders.customer_id,
        sq_stg_orders.location_id,
        sq_stg_orders.ordered_at_day
    from sq_stg_orders
        inner join sq_stg_order_items
            on sq_stg_order_items.order_id = sq_stg_orders.order_id
),

sq_stg_products as (
    -- Source Qualifier SQ_STG_PRODUCTS
    select
        stg_products.product_id,
        stg_products.product_name,
        stg_products.product_type,
        stg_products.product_price_cents,
        stg_products.product_price,
        stg_products.product_description,
        stg_products.is_food_item,
        stg_products.is_drink_item
    from {{ ref('stg_products') }} as stg_products
),

jnr_add_products as (
    -- Joiner JNR_ADD_PRODUCTS
    -- Normal Join (master jnr_items_orders, detail sq_stg_products)
    select
        jnr_items_orders.order_item_id,
        jnr_items_orders.order_id,
        jnr_items_orders.product_id,
        jnr_items_orders.customer_id,
        jnr_items_orders.location_id,
        jnr_items_orders.ordered_at_day,
        sq_stg_products.product_name,
        sq_stg_products.product_type,
        sq_stg_products.product_price,
        sq_stg_products.is_food_item,
        sq_stg_products.is_drink_item
    from sq_stg_products
        inner join jnr_items_orders
            on jnr_items_orders.product_id = sq_stg_products.product_id
),

sq_stg_customers as (
    -- Source Qualifier SQ_STG_CUSTOMERS
    select
        stg_customers.customer_id,
        stg_customers.customer_name
    from {{ ref('stg_customers') }} as stg_customers
),

jnr_add_customers as (
    -- Joiner JNR_ADD_CUSTOMERS
    -- Master Outer Join (master jnr_add_products, detail sq_stg_customers)
    select
        jnr_add_products.order_item_id,
        jnr_add_products.order_id,
        jnr_add_products.product_id,
        jnr_add_products.customer_id,
        jnr_add_products.location_id,
        jnr_add_products.ordered_at_day,
        jnr_add_products.product_name,
        jnr_add_products.product_type,
        jnr_add_products.product_price,
        jnr_add_products.is_food_item,
        jnr_add_products.is_drink_item,
        sq_stg_customers.customer_name
    from sq_stg_customers
        left join jnr_add_products
            on jnr_add_products.customer_id = sq_stg_customers.customer_id
),

sq_stg_locations as (
    -- Source Qualifier SQ_STG_LOCATIONS
    select
        stg_locations.location_id,
        stg_locations.location_name,
        stg_locations.opened_date,
        stg_locations.tax_rate,
        stg_locations.region
    from {{ ref('stg_locations') }} as stg_locations
),

jnr_add_locations as (
    -- Joiner JNR_ADD_LOCATIONS
    -- Master Outer Join (master jnr_add_customers, detail sq_stg_locations)
    select
        jnr_add_customers.order_item_id,
        jnr_add_customers.order_id,
        jnr_add_customers.product_id,
        jnr_add_customers.customer_id,
        jnr_add_customers.location_id,
        jnr_add_customers.ordered_at_day,
        jnr_add_customers.product_name,
        jnr_add_customers.product_type,
        jnr_add_customers.product_price,
        jnr_add_customers.is_food_item,
        jnr_add_customers.is_drink_item,
        jnr_add_customers.customer_name,
        sq_stg_locations.location_name,
        sq_stg_locations.tax_rate,
        sq_stg_locations.region
    from sq_stg_locations
        left join jnr_add_customers
            on jnr_add_customers.location_id = sq_stg_locations.location_id
),

sq_stg_supplies as (
    -- Source Qualifier SQ_STG_SUPPLIES
    select
        stg_supplies.supply_id,
        stg_supplies.supply_name,
        stg_supplies.supply_cost_cents,
        stg_supplies.supply_cost,
        stg_supplies.is_perishable,
        stg_supplies.product_id
    from {{ ref('stg_supplies') }} as stg_supplies
),

srt_supplies as (
    -- Sorter SRT_SUPPLIES
    -- sort order dropped: a table or view has no row order
    select
        sq_stg_supplies.product_id,
        sq_stg_supplies.supply_cost,
        sq_stg_supplies.is_perishable
    from sq_stg_supplies
),

agg_supplies_by_product as (
    -- Aggregator AGG_SUPPLIES_BY_PRODUCT
    select
        srt_supplies.product_id,
        sum(srt_supplies.supply_cost) as supply_cost_per_product,
        max(srt_supplies.is_perishable) as has_perishable_supply
    from srt_supplies
    group by srt_supplies.product_id
),

jnr_add_supplies as (
    -- Joiner JNR_ADD_SUPPLIES
    -- Master Outer Join (master jnr_add_locations, detail agg_supplies_by_product)
    select
        jnr_add_locations.order_item_id,
        jnr_add_locations.order_id,
        jnr_add_locations.product_id,
        jnr_add_locations.customer_id,
        jnr_add_locations.location_id,
        jnr_add_locations.ordered_at_day,
        jnr_add_locations.product_name,
        jnr_add_locations.product_type,
        jnr_add_locations.product_price,
        jnr_add_locations.is_food_item,
        jnr_add_locations.is_drink_item,
        jnr_add_locations.customer_name,
        jnr_add_locations.location_name,
        jnr_add_locations.tax_rate,
        jnr_add_locations.region,
        agg_supplies_by_product.supply_cost_per_product,
        agg_supplies_by_product.has_perishable_supply
    from agg_supplies_by_product
        left join jnr_add_locations
            on jnr_add_locations.product_id = agg_supplies_by_product.product_id
),

exp_item_calculations as (
    -- Expression EXP_ITEM_CALCULATIONS
    select
        jnr_add_supplies.order_item_id,
        jnr_add_supplies.order_id,
        jnr_add_supplies.product_id,
        jnr_add_supplies.customer_id,
        jnr_add_supplies.location_id,
        jnr_add_supplies.ordered_at_day,
        jnr_add_supplies.product_name,
        jnr_add_supplies.product_type,
        jnr_add_supplies.product_price,
        jnr_add_supplies.is_food_item,
        jnr_add_supplies.is_drink_item,
        coalesce(jnr_add_supplies.customer_name, 'Unknown') as customer_name,
        coalesce(jnr_add_supplies.location_name, 'Unknown') as location_name,
        coalesce(jnr_add_supplies.region, 'Unknown') as region,
        jnr_add_supplies.product_price as item_revenue,
        coalesce(jnr_add_supplies.supply_cost_per_product, 0) as item_cogs,
        jnr_add_supplies.product_price - coalesce(jnr_add_supplies.supply_cost_per_product, 0) as item_gross_profit,
        case when jnr_add_supplies.product_price = 0 then 0 else (jnr_add_supplies.product_price - coalesce(jnr_add_supplies.supply_cost_per_product, 0)) / jnr_add_supplies.product_price end as item_gross_margin_pct,
        jnr_add_supplies.product_price * coalesce(jnr_add_supplies.tax_rate, 0) as item_tax_estimate,
        jnr_add_supplies.product_price + jnr_add_supplies.product_price * coalesce(jnr_add_supplies.tax_rate, 0) as item_total_estimate,
        coalesce(jnr_add_supplies.has_perishable_supply, 0) as has_perishable_supply
    from jnr_add_supplies
),

srt_order_id as (
    -- Sorter SRT_ORDER_ID
    -- sort order dropped: a table or view has no row order
    select
        exp_item_calculations.order_id,
        exp_item_calculations.order_item_id,
        exp_item_calculations.product_id,
        exp_item_calculations.customer_id,
        exp_item_calculations.customer_name,
        exp_item_calculations.location_id,
        exp_item_calculations.location_name,
        exp_item_calculations.region,
        exp_item_calculations.ordered_at_day,
        exp_item_calculations.product_name,
        exp_item_calculations.product_type,
        exp_item_calculations.product_price,
        exp_item_calculations.is_food_item,
        exp_item_calculations.is_drink_item,
        exp_item_calculations.item_revenue,
        exp_item_calculations.item_cogs,
        exp_item_calculations.item_gross_profit,
        exp_item_calculations.item_gross_margin_pct,
        exp_item_calculations.item_tax_estimate,
        exp_item_calculations.item_total_estimate,
        exp_item_calculations.has_perishable_supply
    from exp_item_calculations
)

select
    srt_order_id.order_item_id,
    srt_order_id.order_id,
    srt_order_id.product_id,
    srt_order_id.customer_id,
    srt_order_id.customer_name,
    srt_order_id.location_id,
    srt_order_id.location_name,
    srt_order_id.region,
    srt_order_id.ordered_at_day,
    srt_order_id.product_name,
    srt_order_id.product_type,
    srt_order_id.product_price,
    srt_order_id.is_food_item,
    srt_order_id.is_drink_item,
    srt_order_id.item_revenue,
    srt_order_id.item_cogs,
    srt_order_id.item_gross_profit,
    srt_order_id.item_gross_margin_pct,
    srt_order_id.item_tax_estimate,
    srt_order_id.item_total_estimate,
    srt_order_id.has_perishable_supply
from srt_order_id
